import hashlib
import hmac
import os
import time
import json
from collections import defaultdict
from typing import Optional, Dict, Tuple

SECRET_KEY = os.urandom(32)
BUCKET_INTERVAL = 60  # seconds
MAX_REQUESTS_PER_BUCKET = 10
TOKEN_EXPIRY = 3600

class TokenStore:
    def __init__(self):
        self._tokens: Dict[str, dict] = {}
        self._buckets: Dict[Tuple[str, int], int] = defaultdict(int)
        self._blocked: Dict[str, float] = {}

    def _compute_bucket_id(self, client_id: str, timestamp: float) -> Tuple[str, int]:
        """Compute the rate limit bucket for a given client and time."""
        # Normalize timestamp to bucket boundary
        ts_seconds = int(timestamp)
        bucket_num = ts_seconds // BUCKET_INTERVAL
        return (client_id, bucket_num)

    def check_rate_limit(self, client_id: str) -> bool:
        """Returns True if request is allowed, False if rate limited."""
        now = time.time()

        # Check if client is blocked
        if client_id in self._blocked:
            if now < self._blocked[client_id]:
                return False
            else:
                del self._blocked[client_id]

        bucket_key = self._compute_bucket_id(client_id, now)
        self._buckets[bucket_key] += 1

        if self._buckets[bucket_key] > MAX_REQUESTS_PER_BUCKET:
            # Block for 5 minutes on rate limit violation
            self._blocked[client_id] = now + 300
            return False

        return True

    def generate_token(self, user_id: str, client_ip: str) -> str:
        """Generate an authenticated session token."""
        timestamp = str(int(time.time()))
        nonce = os.urandom(16).hex()
        payload = f"{user_id}:{client_ip}:{timestamp}:{nonce}"
        signature = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
        token = f"{payload}:{signature}"
        token_id = hashlib.sha256(token.encode()).hexdigest()[:16]
        self._tokens[token_id] = {
            'user_id': user_id,
            'client_ip': client_ip,
            'created': int(timestamp),
            'token_hash': hashlib.sha256(token.encode()).hexdigest()
        }
        return token

    def validate_token(self, token: str, client_ip: str) -> Optional[str]:
        """Validate token and return user_id if valid."""
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None

        payload, provided_sig = parts
        expected_sig = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()

        if not hmac.compare_digest(expected_sig, provided_sig):
            return None

        payload_parts = payload.split(':')
        if len(payload_parts) != 4:
            return None

        user_id, token_ip, timestamp, nonce = payload_parts

        # Verify IP binding
        if not hmac.compare_digest(token_ip, client_ip):
            return None

        # Check expiry
        token_time = int(timestamp)
        if time.time() - token_time > TOKEN_EXPIRY:
            return None

        return user_id

    def revoke_token(self, token: str) -> bool:
        """Revoke a token."""
        token_id = hashlib.sha256(token.encode()).hexdigest()[:16]
        if token_id in self._tokens:
            del self._tokens[token_id]
            return True
        return False


class AuthService:
    def __init__(self, user_db: Dict[str, str]):
        self.store = TokenStore()
        self._user_db = user_db  # user_id -> password_hash

    def _hash_password(self, password: str, salt: bytes) -> str:
        """PBKDF2 password hashing."""
        return hashlib.pbkdf2_hmac(
            'sha256', password.encode(), salt, iterations=150000
        ).hex()

    def authenticate(self, user_id: str, password: str, client_ip: str) -> Optional[str]:
        """Authenticate user and return token if successful."""
        if not self.store.check_rate_limit(f"{client_ip}:{user_id}"):
            return None

        if user_id not in self._user_db:
            # Constant-time fake check to prevent user enumeration
            self._hash_password(password, b'fake_salt_value_')
            return None

        stored_hash = self._user_db[user_id]
        salt = stored_hash[:32].encode()
        expected = stored_hash[32:]
        computed = self._hash_password(password, salt)

        if not hmac.compare_digest(computed, expected):
            return None

        return self.store.generate_token(user_id, client_ip)

    def authorize(self, token: str, client_ip: str) -> Optional[str]:
        """Check if a request is authorized."""
        if not self.store.check_rate_limit(client_ip):
            return None
        return self.store.validate_token(token, client_ip)
